import pathlib,json,numpy as np
R=pathlib.Path(__file__).resolve().parent;z=np.load(R/'SMOOTH_DAG_PAIR.npz');t=z['t'];p=z['PCC'];E0=z['energy1'];E1=z['energy2'];times=[0,.5,1,1.5,2,2.5,3,6];epsE=.1;clock=.01;Q=5.992115637319317;edotbound=1.25*Q
rows=[]
for tt in times:
 eA=float(np.interp(tt,t,E0));eB=float(np.interp(tt,t,E1));pp=float(np.interp(tt,t,p));margin=abs(eA-eB)/2-epsE-edotbound*clock
 rows.append({'time_seconds':tt,'same_site_same_clock_same_onebit_budget':True,'SOC_world0':eA,'SOC_world1':eB,'SOC_bit_threshold':(eA+eB)/2,'SOC_robust_margin':margin,'PCC_world0':pp,'PCC_world1':pp,'PCC_best_possible_bit_margin':0})
best=max(rows,key=lambda x:x['SOC_robust_margin'])
out={'scope':'two-site label swap for source of high compute task, NOT different exposedPCCsource; fully synthetic smooth lossy finitePCS pair','world0':{'siteA_high_slot':2,'siteB_high_slot':3},'world1':{'siteA_high_slot':3,'siteB_high_slot':2},'site_contracts_identical':True,'same_grid_initial_state_required':True,'same_complete_nodal_PQ':True,'Q_in_both_worlds':'same fixed trajectory','same_PCS_initial_state':0,'same_initial_buffer_energy_each_site':9,'same_work_total_each_site':48,'deterministic_grid_corollary':'same complete nodalP/Q and same initial condition imply same solution and every downstream causal measurement under a well-posed grid model','measurement_comparison':{'site_identity':'siteA fixed and known to both methods','time_grid':times,'communication_budget':'one bit at same selected time; no private task metadata','PCC_noise':'even exact noiseless completePCC cannot distinguish; any equal noise law or same bounded-error witness preserves the overlap','SOC_energy_error':epsE,'clock_error_seconds':clock,'worst_energy_slope':edotbound,'no_total_sensor_cost_claim':True},'queries':rows,'selected_query':best,'unknown_mapping_ablation':'swapping site identity leaves unlabelled SOC multiset and totalSOC identical, so no distinction','tests':{'all_nodalPCC_equal':True,'all_totalSOC_equal':bool(max(abs(E0+E1-18))<1e-10),'best_SOC_query_robust':best['SOC_robust_margin']>0,'best_time2':best['time_seconds']==2,'allPCC_margins0':all(x['PCC_best_possible_bit_margin']==0 for x in rows)}}
np.savez_compressed(R/'TWO_SITE_WORLD_WITNESS.npz',t=t,PCC_A_world0=p,PCC_A_world1=p,PCC_B_world0=p,PCC_B_world1=p,load_A_world0=z['load1'],load_A_world1=z['load2'],load_B_world0=z['load2'],load_B_world1=z['load1'],energy_A_world0=E0,energy_A_world1=E1,energy_B_world0=E1,energy_B_world1=E0)
(R/'TWO_SITE_MEASUREMENT_DESIGN.json').write_text(json.dumps(out,indent=2));print(json.dumps({'selected':best,'tests':out['tests']},indent=2));assert all(out['tests'].values())
